// Serves the whole studio as one self-contained HTML page.
// The markup lives here on purpose: no CDN, no external hosting, nothing to
// deploy next to n8n. Values from Settings (UI) are injected as a JSON blob so
// the page never hardcodes configuration.
const cfg = $('Settings (UI)').first().json;

const ui = {
  title: cfg.ui_title || 'Gemini Image Studio',
  subtitle: cfg.ui_subtitle || '',
  maxSidePx: Number(cfg.max_side_px) || 1600,
  maxImages: Number(cfg.max_images) || 2,
  maxFileMb: Number(cfg.max_file_mb) || 8,
};

const HEAD = "<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Gemini Image Studio</title>
<style>
  *, *::before, *::after { box-sizing: border-box; }
  :root {
    --bg: #0b0d12;
    --bg-soft: #11141c;
    --panel: #151925;
    --panel-2: #1b2030;
    --line: #262d40;
    --text: #e8ecf6;
    --muted: #8b95ad;
    --muted-2: #626d86;
    --accent: #7c8cff;
    --accent-soft: rgba(124, 140, 255, 0.14);
    --accent-line: rgba(124, 140, 255, 0.45);
    --ok: #37d399;
    --warn: #f6c35c;
    --err: #ff7b72;
    --radius: 14px;
    --radius-sm: 10px;
    --shadow: 0 18px 45px rgba(0, 0, 0, 0.45);
    --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  }
  html, body { margin: 0; padding: 0; }
  body {
    background:
      radial-gradient(1100px 620px at 12% -8%, #1a2140 0%, transparent 62%),
      radial-gradient(900px 520px at 92% 4%, #171b33 0%, transparent 58%),
      var(--bg);
    color: var(--text);
    font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    min-height: 100vh;
  }
  .wrap { max-width: 1040px; margin: 0 auto; padding: 34px 20px 96px; }

  header { margin-bottom: 26px; }
  .brand { display: flex; align-items: center; gap: 11px; }
  .glyph {
    width: 32px; height: 32px; flex: none; border-radius: 9px;
    background: linear-gradient(140deg, var(--accent), #4de0c4);
    display: grid; place-items: center; font-size: 17px; color: #0b0d12;
    box-shadow: 0 6px 18px rgba(124, 140, 255, 0.35);
  }
  h1 { margin: 0; font-size: 21px; font-weight: 650; letter-spacing: -0.015em; }
  .sub { margin: 9px 0 0; color: var(--muted); max-width: 62ch; font-size: 14px; }

  .card {
    background: linear-gradient(180deg, var(--panel) 0%, var(--bg-soft) 100%);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    padding: 20px;
    margin-bottom: 16px;
    box-shadow: var(--shadow);
  }
  .step { display: flex; align-items: baseline; gap: 10px; margin: 0 0 15px; }
  .step .n {
    font: 600 11px/1 var(--mono); color: var(--accent);
    background: var(--accent-soft); border: 1px solid var(--accent-line);
    border-radius: 6px; padding: 5px 7px; letter-spacing: 0.06em;
  }
  .step h2 { margin: 0; font-size: 14px; font-weight: 600; letter-spacing: 0.01em; }
  .step .opt { margin-left: auto; font-size: 12px; color: var(--muted-2); }

  .modes { display: grid; grid-template-columns: repeat(auto-fill, minmax(226px, 1fr)); gap: 10px; }
  .mode {
    text-align: left; cursor: pointer; color: inherit; font: inherit;
    background: var(--panel-2); border: 1px solid var(--line);
    border-radius: var(--radius-sm); padding: 13px 14px;
    display: grid; grid-template-columns: 24px 1fr; gap: 11px;
    transition: border-color .14s, background .14s, transform .14s;
  }
  .mode:hover { border-color: #33405c; transform: translateY(-1px); }
  .mode[aria-pressed="true"] { border-color: var(--accent-line); background: var(--accent-soft); }
  .mode .ic { font-size: 17px; line-height: 1.3; color: var(--accent); }
  .mode b { display: block; font-size: 13.5px; font-weight: 600; }
  .mode .d { display: block; color: var(--muted); font-size: 12.5px; margin-top: 3px; }
  .mode em { display: block; font-style: normal; color: var(--warn); font-size: 11.5px; margin-top: 5px; }

  .slots { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  .slot {
    position: relative; border: 1.5px dashed var(--line);
    border-radius: var(--radius-sm); background: var(--panel-2);
    min-height: 168px; display: grid; place-items: center; text-align: center;
    padding: 16px; cursor: pointer; overflow: hidden;
    transition: border-color .14s, background .14s;
  }
  .slot:hover, .slot.hot { border-color: var(--accent-line); background: var(--accent-soft); }
  .slot .ph { color: var(--muted); font-size: 13px; }
  .slot .ph strong { display: block; color: var(--text); font-size: 13.5px; margin-bottom: 5px; font-weight: 600; }
  .slot .ph small { display: block; color: var(--muted-2); font-size: 11.5px; margin-top: 7px; }
  .slot img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; background: #0a0c11; }
  .slot .tag {
    position: absolute; left: 8px; top: 8px; z-index: 2;
    font: 600 10.5px/1 var(--mono); letter-spacing: 0.05em; text-transform: uppercase;
    background: rgba(8, 10, 16, 0.82); border: 1px solid var(--line);
    color: var(--muted); padding: 5px 7px; border-radius: 6px;
  }
  .slot .kill {
    position: absolute; right: 8px; top: 8px; z-index: 2; cursor: pointer;
    width: 26px; height: 26px; border-radius: 7px; border: 1px solid var(--line);
    background: rgba(8, 10, 16, 0.82); color: var(--text); font-size: 14px; line-height: 1;
    display: grid; place-items: center;
  }
  .slot .kill:hover { border-color: var(--err); color: var(--err); }
  .slot .meta {
    position: absolute; left: 0; right: 0; bottom: 0; z-index: 2;
    background: rgba(8, 10, 16, 0.86); border-top: 1px solid var(--line);
    font: 11.5px/1 var(--mono); color: var(--muted); padding: 7px 9px;
    white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  }
  .hint { margin: 11px 0 0; font-size: 12.5px; color: var(--muted-2); }

  .grid2 { display: grid; grid-template-columns: 1fr 200px; gap: 12px; }
  label.f { display: block; }
  label.f > span { display: block; font-size: 12px; color: var(--muted); margin-bottom: 6px; letter-spacing: 0.01em; }
  input[type="text"], select, textarea {
    width: 100%; background: #0d1017; color: var(--text);
    border: 1px solid var(--line); border-radius: var(--radius-sm);
    padding: 10px 12px; font: inherit; outline: none;
  }
  input[type="text"]:focus, select:focus, textarea:focus { border-color: var(--accent-line); box-shadow: 0 0 0 3px var(--accent-soft); }
  textarea { min-height: 92px; resize: vertical; }
  .row-notes { margin-top: 12px; }
  .check { display: flex; align-items: center; gap: 9px; margin-top: 12px; font-size: 13px; color: var(--muted); cursor: pointer; }
  .check input { width: 16px; height: 16px; accent-color: var(--accent); }

  .go {
    width: 100%; cursor: pointer; font: 600 15px/1 inherit; color: #0b0d12;
    background: linear-gradient(135deg, #9aa6ff, #6ad9c0);
    border: 0; border-radius: var(--radius); padding: 15px 18px;
    box-shadow: 0 12px 30px rgba(124, 140, 255, 0.28);
    transition: filter .14s, transform .14s;
  }
  .go:hover:not(:disabled) { filter: brightness(1.06); transform: translateY(-1px); }
  .go:disabled { cursor: not-allowed; filter: grayscale(0.55) brightness(0.7); box-shadow: none; }

  .status { margin-top: 14px; display: none; align-items: center; gap: 11px; font-size: 13.5px; }
  .status.on { display: flex; }
  .spin {
    width: 16px; height: 16px; flex: none; border-radius: 50%;
    border: 2px solid var(--line); border-top-color: var(--accent);
    animation: spin .7s linear infinite;
  }
  @keyframes spin { to { transform: rotate(360deg); } }
  .status .t { font-family: var(--mono); color: var(--muted-2); font-size: 12.5px; }

  .alert {
    display: none; margin-top: 14px; border-radius: var(--radius-sm);
    border: 1px solid rgba(255, 123, 114, 0.4); background: rgba(255, 123, 114, 0.09);
    color: #ffd9d6; padding: 13px 15px; font-size: 13.5px;
  }
  .alert.on { display: block; }
  .alert b { display: block; margin-bottom: 4px; color: var(--err); }

  .result { display: none; }
  .result.on { display: block; }
  .shot { border-radius: var(--radius-sm); overflow: hidden; border: 1px solid var(--line); background: #0a0c11; }
  .shot img { display: block; width: 100%; height: auto; }
  .rmeta { display: flex; flex-wrap: wrap; gap: 7px; margin: 13px 0; }
  .pill {
    font: 11.5px/1 var(--mono); color: var(--muted);
    background: var(--panel-2); border: 1px solid var(--line);
    padding: 6px 9px; border-radius: 999px;
  }
  .pill.good { color: var(--ok); border-color: rgba(55, 211, 153, 0.35); background: rgba(55, 211, 153, 0.08); }
  .acts { display: flex; flex-wrap: wrap; gap: 9px; }
  .btn {
    cursor: pointer; font: 600 13px/1 inherit; color: var(--text);
    background: var(--panel-2); border: 1px solid var(--line);
    border-radius: var(--radius-sm); padding: 11px 14px; text-decoration: none;
    display: inline-flex; align-items: center; gap: 7px;
  }
  .btn:hover { border-color: var(--accent-line); color: #fff; }
  .btn.pri { background: var(--accent-soft); border-color: var(--accent-line); }
  details { margin-top: 14px; }
  summary { cursor: pointer; font-size: 12.5px; color: var(--muted); }
  details pre {
    margin: 10px 0 0; white-space: pre-wrap; word-break: break-word;
    font: 12px/1.6 var(--mono); color: var(--muted);
    background: #0d1017; border: 1px solid var(--line);
    border-radius: var(--radius-sm); padding: 13px;
  }

  .hist { display: none; }
  .hist.on { display: block; }
  .strip { display: flex; gap: 9px; overflow-x: auto; padding-bottom: 4px; }
  .strip button {
    flex: none; width: 84px; height: 84px; padding: 0; cursor: pointer;
    border-radius: var(--radius-sm); border: 1px solid var(--line);
    background: #0a0c11; overflow: hidden;
  }
  .strip button:hover { border-color: var(--accent-line); }
  .strip img { width: 100%; height: 100%; object-fit: cover; display: block; }

  footer { margin-top: 26px; color: var(--muted-2); font-size: 12px; text-align: center; }
  footer code { font-family: var(--mono); color: var(--muted); }

  @media (max-width: 700px) {
    .wrap { padding: 24px 15px 80px; }
    .slots, .grid2 { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
<main class="wrap">
  <header>
    <div class="brand">
      <div class="glyph">&#9672;</div>
      <h1 id="uiTitle">Gemini Image Studio</h1>
    </div>
    <p class="sub" id="uiSub"></p>
  </header>

  <section class="card">
    <div class="step"><span class="n">01</span><h2>What do you need</h2></div>
    <div class="modes" id="modes"></div>
  </section>

  <section class="card">
    <div class="step"><span class="n">02</span><h2>Reference images</h2><span class="opt" id="slotOpt"></span></div>
    <div class="slots">
      <div class="slot" id="slot0" tabindex="0" role="button" aria-label="Upload main image"></div>
      <div class="slot" id="slot1" tabindex="0" role="button" aria-label="Upload second image"></div>
    </div>
    <p class="hint" id="slotHint"></p>
  </section>

  <section class="card">
    <div class="step"><span class="n">03</span><h2>Details</h2><span class="opt">All optional except in Freeform prompt</span></div>
    <div class="grid2">
      <label class="f"><span>Brand or product</span><input type="text" id="brand" placeholder="e.g. Nike Air Max, Viva Aerobus" maxlength="200" autocomplete="off"></label>
      <label class="f"><span>Output format</span>
        <select id="format">
          <option value="auto">Automatic</option>
          <option value="1:1">Square 1:1</option>
          <option value="4:5">Portrait 4:5</option>
          <option value="9:16">Portrait 9:16</option>
          <option value="16:9">Landscape 16:9</option>
        </select>
      </label>
    </div>
    <label class="f row-notes"><span id="notesLabel">Additional instructions</span><textarea id="notes" maxlength="1500" placeholder="Details to steer the result: lighting, palette, setting, audience&hellip;"></textarea></label>
    <label class="check"><input type="checkbox" id="noText"> No text or watermarks in the image</label>
  </section>

  <button class="go" id="go">Generate image</button>

  <div class="status" id="status"><div class="spin"></div><div id="statusMsg">Generating&hellip;</div><div class="t" id="timer">0.0s</div></div>
  <div class="alert" id="alert"><b>Could not generate</b><span id="alertMsg"></span></div>

  <section class="card result" id="result">
    <div class="step"><span class="n">04</span><h2>Result</h2></div>
    <div class="shot"><img id="outImg" alt="Generated image"></div>
    <div class="rmeta" id="outMeta"></div>
    <div class="acts">
      <a class="btn pri" id="dl" download>Download</a>
      <button class="btn" id="reuse">Use as main image</button>
      <button class="btn" id="again">Generate again</button>
      <button class="btn" id="copyPrompt">Copy prompt</button>
    </div>
    <details><summary>See the exact prompt Gemini received</summary><pre id="outPrompt"></pre></details>
  </section>

  <section class="card hist" id="hist">
    <div class="step"><span class="n">05</span><h2>This session</h2><span class="opt">Cleared on reload</span></div>
    <div class="strip" id="strip"></div>
  </section>

  <footer>Generated entirely inside n8n with <code>Gemini</code> &middot; images are resized in your browser before upload</footer>
</main>

<script>
(function () {
  'use strict';

  var CFG = ";

const TAIL = ";

  // Keys must match the MODES object in the "Validate & build prompt" node.
  var MODES = [
    { key: 'product_ad',        ic: '◆', label: 'Product ad',           desc: 'High-impact advertising composition, ready for a campaign.', needs: 1 },
    { key: 'aesthetic',         ic: '◇', label: 'Aesthetic product',    desc: 'Minimal lifestyle styling, natural light, aesthetic feed.', needs: 1 },
    { key: 'packshot',          ic: '▣', label: 'Clean packshot',       desc: 'Product on a neutral background, catalogue or e-commerce style.', needs: 1 },
    { key: 'space_with_people', ic: '◎', label: 'Space with people',    desc: 'Edits your photo of the venue and fills it with people.', needs: 1 },
    { key: 'space_with_logo',   ic: '⌘', label: 'Space with logo',      desc: 'Places the logo on a facade, signage or screens.', needs: 2 },
    { key: 'freeform',          ic: '✎', label: 'Freeform prompt',      desc: 'You describe the image. With or without a reference.', needs: 0 }
  ];

  var SLOT_LABELS = ['Main image', 'Logo or 2nd reference'];
  var ALLOWED = ['image/jpeg', 'image/png', 'image/webp'];

  var state = { mode: MODES[0].key, files: [null, null], history: [], busy: false };
  var tick = null;

  function el(id) { return document.getElementById(id); }
  var slotEls = [el('slot0'), el('slot1')];

  el('uiTitle').textContent = CFG.title || 'Gemini Image Studio';
  document.title = CFG.title || 'Gemini Image Studio';
  el('uiSub').textContent = CFG.subtitle || '';
  el('slotOpt').textContent = 'Up to ' + (CFG.maxImages || 2) + ' · max ' + (CFG.maxSidePx || 1600) + 'px per side';

  function currentMode() {
    for (var i = 0; i < MODES.length; i++) {
      if (MODES[i].key === state.mode) { return MODES[i]; }
    }
    return MODES[0];
  }

  function esc(s) {
    return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function renderModes() {
    var box = el('modes');
    box.innerHTML = '';
    MODES.forEach(function (m) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'mode';
      b.setAttribute('aria-pressed', m.key === state.mode ? 'true' : 'false');
      var note = '';
      if (m.needs === 2) { note = '<em>Needs 2 images</em>'; }
      if (m.needs === 0) { note = '<em>Image is optional</em>'; }
      b.innerHTML = '<span class="ic">' + m.ic + '</span><span><b>' + esc(m.label) +
        '</b><span class="d">' + esc(m.desc) + '</span>' + note + '</span>';
      b.addEventListener('click', function () {
        state.mode = m.key;
        renderModes();
        renderHint();
      });
      box.appendChild(b);
    });
  }

  function renderHint() {
    var m = currentMode();
    var have = state.files.filter(Boolean).length;
    var msg;
    if (m.key === 'space_with_logo') {
      msg = 'Upload the photo of the space first, then the logo. Order matters.';
    } else if (m.needs === 0) {
      msg = 'With no image, Gemini builds the scene from scratch out of your description.';
    } else {
      msg = 'The 2nd image is optional: it is used as an extra style or context reference.';
    }
    if (have < m.needs) {
      msg = 'Missing images: this mode needs ' + m.needs + '. ' + msg;
    }
    el('slotHint').textContent = msg;
    el('notesLabel').textContent = m.key === 'freeform' ? 'Describe the image (required)' : 'Additional instructions';
    el('go').disabled = state.busy || have < m.needs;
  }

  function renderSlot(i) {
    var host = slotEls[i];
    var f = state.files[i];
    host.innerHTML = '';
    if (!f) {
      var ph = document.createElement('div');
      ph.className = 'ph';
      ph.innerHTML = '<strong>' + SLOT_LABELS[i] + '</strong>Drag, paste or click<small>' +
        (i === 0 ? 'JPG · PNG · WebP' : 'Optional, depends on the mode') + '</small>';
      host.appendChild(ph);
      return;
    }
    var img = document.createElement('img');
    img.src = f.data;
    img.alt = SLOT_LABELS[i];
    var tag = document.createElement('span');
    tag.className = 'tag';
    tag.textContent = i === 0 ? 'main' : 'logo / ref 2';
    var kill = document.createElement('button');
    kill.type = 'button';
    kill.className = 'kill';
    kill.title = 'Remove';
    kill.textContent = '✕';
    kill.addEventListener('click', function (ev) {
      ev.stopPropagation();
      state.files[i] = null;
      renderSlot(i);
      renderHint();
    });
    var meta = document.createElement('div');
    meta.className = 'meta';
    meta.textContent = (f.w ? f.w + '×' + f.h + ' · ' : '') +
      Math.round(f.bytes / 1024) + ' KB · ' + f.type.replace('image/', '');
    host.appendChild(img);
    host.appendChild(tag);
    host.appendChild(kill);
    host.appendChild(meta);
  }

  function shrink(file, slot) {
    return new Promise(function (resolve, reject) {
      var keepAlpha = slot === 1 || file.type === 'image/png';
      var maxSide = slot === 1 ? Math.min(1024, CFG.maxSidePx || 1600) : (CFG.maxSidePx || 1600);
      var url = URL.createObjectURL(file);
      var img = new Image();
      img.onload = function () {
        var w = img.naturalWidth;
        var h = img.naturalHeight;
        if (!w || !h) {
          URL.revokeObjectURL(url);
          reject(new Error('The image could not be read.'));
          return;
        }
        var k = Math.min(1, maxSide / Math.max(w, h));
        var cw = Math.max(1, Math.round(w * k));
        var ch = Math.max(1, Math.round(h * k));
        var c = document.createElement('canvas');
        c.width = cw;
        c.height = ch;
        var ctx = c.getContext('2d');
        ctx.imageSmoothingQuality = 'high';
        ctx.drawImage(img, 0, 0, cw, ch);
        URL.revokeObjectURL(url);
        var type = keepAlpha ? 'image/png' : 'image/jpeg';
        var data = keepAlpha ? c.toDataURL('image/png') : c.toDataURL('image/jpeg', 0.92);
        var bytes = Math.round((data.length - data.indexOf(',') - 1) * 0.75);
        resolve({ name: file.name || 'reference', type: type, data: data, w: cw, h: ch, bytes: bytes });
      };
      img.onerror = function () {
        URL.revokeObjectURL(url);
        reject(new Error('Could not open ' + (file.name || 'the file') + '.'));
      };
      img.src = url;
    });
  }

  function accept(file, slot) {
    if (!file) { return; }
    if (ALLOWED.indexOf(file.type) === -1) {
      fail('Unsupported format: ' + (file.type || 'unknown') + '. Use JPG, PNG or WebP.');
      return;
    }
    // The server maps the 1st image to "primary" and the 2nd to "logo". If slot 2
    // gets filled while slot 1 is empty, that image would arrive labelled as the
    // main one, so it is redirected to slot 1 and the order the user sees is the
    // order Gemini receives.
    if (slot === 1 && !state.files[0]) { slot = 0; }
    shrink(file, slot).then(function (out) {
      var cap = (CFG.maxFileMb || 8) * 1024 * 1024;
      if (out.bytes > cap) {
        fail('The image is still larger than ' + (CFG.maxFileMb || 8) + ' MB after compression.');
        return;
      }
      clearAlert();
      state.files[slot] = out;
      renderSlot(slot);
      renderHint();
    }).catch(function (e) {
      fail(e.message || 'Could not process the image.');
    });
  }

  function pick(slot) {
    var input = document.createElement('input');
    input.type = 'file';
    input.accept = ALLOWED.join(',');
    input.addEventListener('change', function () {
      accept(input.files && input.files[0], slot);
    });
    input.click();
  }

  slotEls.forEach(function (host, i) {
    host.addEventListener('click', function () { pick(i); });
    host.addEventListener('keydown', function (ev) {
      if (ev.key === 'Enter' || ev.key === ' ') {
        ev.preventDefault();
        pick(i);
      }
    });
    ['dragenter', 'dragover'].forEach(function (t) {
      host.addEventListener(t, function (ev) {
        ev.preventDefault();
        host.classList.add('hot');
      });
    });
    ['dragleave', 'dragend'].forEach(function (t) {
      host.addEventListener(t, function () { host.classList.remove('hot'); });
    });
    host.addEventListener('drop', function (ev) {
      ev.preventDefault();
      host.classList.remove('hot');
      accept(ev.dataTransfer && ev.dataTransfer.files && ev.dataTransfer.files[0], i);
    });
  });

  document.addEventListener('paste', function (ev) {
    var files = ev.clipboardData && ev.clipboardData.files;
    if (!files || !files.length) { return; }
    accept(files[0], state.files[0] ? 1 : 0);
  });

  function fail(msg) {
    el('alertMsg').textContent = msg;
    el('alert').classList.add('on');
  }

  function clearAlert() { el('alert').classList.remove('on'); }

  function setBusy(on, msg) {
    state.busy = on;
    el('status').classList.toggle('on', on);
    if (msg) { el('statusMsg').textContent = msg; }
    renderHint();
    if (on) {
      var t0 = Date.now();
      el('timer').textContent = '0.0s';
      tick = setInterval(function () {
        el('timer').textContent = ((Date.now() - t0) / 1000).toFixed(1) + 's';
      }, 100);
    } else if (tick) {
      clearInterval(tick);
      tick = null;
    }
  }

  function showInResult(data) {
    el('outImg').src = data.image;
    el('outPrompt').textContent = data.prompt || '';
    el('dl').href = data.image;
    el('dl').setAttribute('download', data.file_name || 'gemini.png');
  }

  function renderResult(data) {
    showInResult(data);
    var pills = [];
    pills.push('<span class="pill good">' + esc(data.mode_label || data.mode || 'done') + '</span>');
    if (data.elapsed_ms) { pills.push('<span class="pill">' + (data.elapsed_ms / 1000).toFixed(1) + ' s</span>'); }
    if (data.bytes) { pills.push('<span class="pill">' + Math.round(data.bytes / 1024) + ' KB</span>'); }
    pills.push('<span class="pill">' + (data.image_count || 0) + ' ref.</span>');
    if (data.mime_type) { pills.push('<span class="pill">' + esc(data.mime_type.replace('image/', '')) + '</span>'); }
    el('outMeta').innerHTML = pills.join('');
    el('result').classList.add('on');
    state.history.unshift(data);
    state.history = state.history.slice(0, 12);
    renderHistory();
    el('result').scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function renderHistory() {
    if (!state.history.length) { return; }
    el('hist').classList.add('on');
    var strip = el('strip');
    strip.innerHTML = '';
    state.history.forEach(function (h) {
      var b = document.createElement('button');
      b.type = 'button';
      b.title = h.mode_label || '';
      var i = document.createElement('img');
      i.src = h.image;
      i.alt = h.mode_label || 'result';
      b.appendChild(i);
      b.addEventListener('click', function () {
        showInResult(h);
        el('result').scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
      strip.appendChild(b);
    });
  }

  function generate() {
    var m = currentMode();
    var imgs = state.files.filter(Boolean);
    if (imgs.length < m.needs) {
      fail('This mode needs ' + m.needs + ' reference image(s).');
      return;
    }
    var notes = el('notes').value.trim();
    if (m.key === 'freeform' && !notes) {
      fail('In Freeform prompt, describe what you want generated.');
      return;
    }

    clearAlert();
    setBusy(true, imgs.length ? 'Editing with Gemini…' : 'Creating with Gemini…');
    el('go').textContent = 'Generating…';

    var ctrl = new AbortController();
    var killer = setTimeout(function () { ctrl.abort(); }, 180000);

    fetch(window.location.href, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        mode: m.key,
        brand: el('brand').value.trim(),
        notes: notes,
        format: el('format').value,
        no_text: el('noText').checked,
        images: imgs.map(function (f) {
          return { name: f.name, type: f.type, data: f.data };
        })
      }),
      signal: ctrl.signal
    }).then(function (res) {
      return res.json().catch(function () {
        throw new Error('The webhook answered ' + res.status + ' with no JSON. Check the execution in n8n.');
      });
    }).then(function (data) {
      if (!data || data.ok !== true) {
        throw new Error((data && data.error) || 'Unexpected response from the workflow.');
      }
      if (!data.image) {
        throw new Error('The workflow returned no image.');
      }
      renderResult(data);
    }).catch(function (e) {
      fail(e.name === 'AbortError'
        ? 'Timed out after 3 minutes. Check the execution in n8n.'
        : (e.message || 'Network error.'));
    }).then(function () {
      clearTimeout(killer);
      setBusy(false);
      el('go').textContent = 'Generate image';
    });
  }

  el('go').addEventListener('click', generate);
  el('again').addEventListener('click', generate);

  // Iterate on the result itself. It goes through the same path as an uploaded
  // file (accept -> shrink) so it gets recompressed and reports real dimensions,
  // instead of re-sending the full PNG Gemini returned.
  el('reuse').addEventListener('click', function () {
    var src = el('outImg').getAttribute('src');
    if (!src) { return; }
    fetch(src).then(function (r) {
      return r.blob();
    }).then(function (blob) {
      state.files[0] = null;
      accept(new File([blob], 'previous-result.png', { type: blob.type || 'image/png' }), 0);
      slotEls[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
    }).catch(function () {
      fail('Could not reuse the result as a reference.');
    });
  });

  el('copyPrompt').addEventListener('click', function () {
    var txt = el('outPrompt').textContent || '';
    var done = function (label) {
      el('copyPrompt').textContent = label;
      setTimeout(function () { el('copyPrompt').textContent = 'Copy prompt'; }, 1600);
    };
    // writeText rejects when the document is not focused or the page is served
    // over plain HTTP. Falling back to selecting the text means Ctrl+C actually
    // works, instead of leaving an unhandled rejection and a lying label.
    var selectIt = function () {
      var pre = el('outPrompt');
      pre.closest('details').open = true;
      var range = document.createRange();
      range.selectNodeContents(pre);
      var sel = window.getSelection();
      sel.removeAllRanges();
      sel.addRange(range);
      done('Selected, press Ctrl+C');
    };
    if (navigator.clipboard) {
      navigator.clipboard.writeText(txt).then(function () {
        done('Copied ✓');
      }).catch(selectIt);
    } else {
      selectIt();
    }
  });

  renderModes();
  renderSlot(0);
  renderSlot(1);
  renderHint();
})();
</script>
</body>
</html>
";

return [{ json: { html: HEAD + JSON.stringify(ui) + TAIL } }];

// Turns one HTTP POST into a Gemini-ready item. Single Code node on purpose:
// validating, decoding base64 into binary properties and assembling the prompt
// are one transaction -- if any part fails the caller must get a clean 400 and no
// Gemini call. Nothing here throws: failures come back as { ok: false, error }
// so the IF node downstream can answer 400 instead of a 500 stack trace.
const started = Date.now();
const cfg = $('Settings (generator)').first().json;
const body = $input.first().json.body || {};

const fail = (error) => [{ json: { ok: false, error: String(error) } }];

// Prompt library. This is the editorial core of the tool: change the wording here
// and every request of that type changes. Keys must match the MODES array in
// "Build studio page".
const MODES = {
  product_ad: {
    label: 'Product ad',
    needs: 1,
    prompt: 'Create a professional, high-impact advertising image for this product. Commercial composition, studio lighting, clean background, ready for social media and marketing campaigns. Highlight the visual benefits of the product.',
  },
  aesthetic: {
    label: 'Aesthetic product',
    needs: 1,
    prompt: 'Create an aesthetic, aspirational image of this product. Minimal lifestyle styling, soft natural light, elegant palette, Instagram/Pinterest aesthetic composition. The product is the hero inside a visually harmonious context.',
  },
  packshot: {
    label: 'Clean packshot',
    needs: 1,
    prompt: 'Cut the product out of the attached image and place it on a neutral, even studio background, catalogue or e-commerce packshot style. Strictly preserve the real shape, colour, materials, textures, labels and details of the product: do not redesign it or invent variants. Soft wrapping light, a subtle realistic contact shadow, no harsh reflections, centred framing with room around it.',
  },
  space_with_people: {
    label: 'Space with people',
    needs: 1,
    prompt: 'Starting from the attached photo of this physical space (a hall, venue, office or stadium), edit that SAME photograph to populate it with people and a lively atmosphere. Do NOT generate a new space and do NOT change the angle, framing, perspective or camera viewpoint: use the original photo as the base background and integrate the people on top of it. Strictly preserve the architecture, proportions, materials, lighting and perspective of the original space -- it must look like the same photo, only now with people in it. Add realistic people consistent with the scale of the venue, lighting consistent with the original light source, correct shadows, and decor appropriate to the type of event. Treat this as a photo edit (inpainting) on the given image, not as an image created from scratch.',
  },
  space_with_logo: {
    label: 'Space with brand logo',
    needs: 2,
    prompt: 'Two images are attached: the FIRST is the physical space (a building, stadium, hall or office); the SECOND is the brand logo. Edit that SAME first photograph to integrate the logo realistically (facade, signage, screens, banners or environmental branding). Do NOT generate a new building or space, and do NOT change the angle, framing, perspective or viewpoint: use the first photo exactly as it is and only place the logo on the surfaces where it belongs. Strictly preserve the architecture, proportions, materials and perspective of the original space -- the result must be the same photo of the building, only now with the logo applied. Adapt the logo to the surface: respect its perspective, curvature, lighting, reflections and shadows so it looks physically present in the place. Treat this as a photo edit (compositing/inpainting) on the given image, not as an image created from scratch.',
  },
  freeform: {
    label: 'Freeform prompt',
    needs: 0,
    prompt: 'Generate the image described below with professional quality and a photorealistic finish unless another style is requested.',
  },
};

const FORMATS = {
  '1:1': 'Deliver the image in a square 1:1 format, suitable for a social feed.',
  '4:5': 'Deliver the image in a vertical 4:5 (portrait) format, suitable for an Instagram feed.',
  '9:16': 'Deliver the image in a vertical 9:16 format, suitable for Stories and Reels.',
  '16:9': 'Deliver the image in a horizontal 16:9 format, suitable for web and presentations.',
};

const modeKey = String(body.mode || '').trim();
const mode = MODES[modeKey];
if (!mode) {
  return fail('Unknown mode: "' + modeKey + '". Valid modes: ' + Object.keys(MODES).join(', ') + '.');
}

const maxImages = Number(cfg.max_images) || 2;
const maxMb = Number(cfg.max_file_mb) || 8;
const allowed = ['image/jpeg', 'image/png', 'image/webp'];

const incoming = Array.isArray(body.images) ? body.images.filter(Boolean) : [];
if (incoming.length > maxImages) {
  return fail('At most ' + maxImages + ' images per request, got ' + incoming.length + '.');
}
if (incoming.length < mode.needs) {
  return fail('"' + mode.label + '" needs ' + mode.needs + ' image' + (mode.needs === 1 ? '' : 's') + ', got ' + incoming.length + '.');
}

const brand = String(body.brand || '').trim().slice(0, 200);
const notes = String(body.notes || '').trim().slice(0, 1500);
if (modeKey === 'freeform' && !notes) {
  return fail('"Freeform prompt" requires a description in the instructions field.');
}

// Decode the browser-side data URLs into real binary properties. The slot names
// are what the Gemini nodes read, so the order the UI sends them in is the order
// Gemini receives them in (space first, logo second).
const slots = ['primary', 'logo'];
const binary = {};
for (let i = 0; i < incoming.length; i++) {
  const img = incoming[i] || {};
  const mime = String(img.type || '').toLowerCase();
  if (!allowed.includes(mime)) {
    return fail('Unsupported format in image ' + (i + 1) + ' (' + (mime || 'unknown') + '). Use JPG, PNG or WebP.');
  }
  const b64 = String(img.data || '').split(',').pop();
  if (!b64) {
    return fail('Image ' + (i + 1) + ' arrived empty.');
  }
  const buf = Buffer.from(b64, 'base64');
  if (!buf.length) {
    return fail('Image ' + (i + 1) + ' could not be decoded.');
  }
  if (buf.length > maxMb * 1024 * 1024) {
    return fail('Image ' + (i + 1) + ' is larger than ' + maxMb + ' MB.');
  }
  binary[slots[i]] = await this.helpers.prepareBinaryData(buf, String(img.name || 'input-' + (i + 1)), mime);
}

const parts = [mode.prompt];
if (modeKey !== 'space_with_logo' && incoming.length === 2) {
  parts.push('The second attached image is an additional style or context reference, not an element to copy literally.');
}
if (brand) {
  parts.push('Brand or product to respect: ' + brand + '.');
}
if (notes) {
  const tidy = /[.!?]$/.test(notes) ? notes : notes + '.';
  parts.push(modeKey === 'freeform' ? tidy : 'Additional directions: ' + tidy);
}
const fmt = FORMATS[String(body.format || 'auto')];
if (fmt) {
  parts.push(fmt);
}
if (body.no_text === true) {
  parts.push('Do not include any text, lettering, invented logos or watermarks.');
}
parts.push('Return only the final image, with no questions and no explanations.');

return [{
  json: {
    ok: true,
    started,
    mode: modeKey,
    mode_label: mode.label,
    image_count: incoming.length,
    brand,
    notes,
    format: String(body.format || 'auto'),
    prompt: parts.join(' '),
  },
  binary,
}];

// Packs Gemini's binary output into the JSON envelope the browser expects.
// A data URL keeps the whole round trip inside n8n: no S3, no public file host,
// no signed links to expire. The page renders it and the download button uses it
// directly.
const meta = $('Validate & build prompt').first().json;
const bin = ($input.first().binary || {}).data;

if (!bin) {
  return [{
    json: {
      ok: false,
      error: 'Gemini answered without an image. That usually happens when the prompt reads as a question or the reference is refused by policy: reword the instructions or try another image.',
    },
  }];
}

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const mimeType = bin.mimeType || 'image/png';
const ext = String(bin.fileExtension || mimeType.split('/').pop() || 'png').replace('jpeg', 'jpg');
const stamp = new Date().toISOString().slice(0, 19).replace('T', '_').replace(/:/g, '-');

return [{
  json: {
    ok: true,
    mode: meta.mode,
    mode_label: meta.mode_label,
    prompt: meta.prompt,
    image_count: meta.image_count,
    mime_type: mimeType,
    bytes: buf.length,
    file_name: 'gemini-' + meta.mode + '-' + stamp + '.' + ext,
    image: 'data:' + mimeType + ';base64,' + buf.toString('base64'),
    elapsed_ms: Date.now() - Number(meta.started || Date.now()),
  },
}];
